 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    blocks = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                cr, cc = q.popleft()
                cells.append((cr, cc))
                for nr, nc in ((cr - 1, cc), (cr + 1, cc), (cr, cc - 1), (cr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen
                            and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        q.append((nr, nc))
            rs = [x for x, _ in cells]
            cs = [y for _, y in cells]
            r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
            if (r1 - r0 == 2 and c1 - c0 == 2 and len(cells) == 9
                    and all(grid[rr][cc] == color
                            for rr in range(r0, r1 + 1)
                            for cc in range(c0, c1 + 1))):
                blocks.append((r0 + 1, c0 + 1, color))

    # Each solid 3x3 block projects its color along its central row and column.
    # Where projections of different colors cross, leave the cell blank.
    row_colors = {}
    col_colors = {}
    for r, c, color in blocks:
        row_colors.setdefault(r, set()).add(color)
        col_colors.setdefault(c, set()).add(color)

    out = [row[:] for row in grid]
    for r, colors in row_colors.items():
        for c in range(w):
            vertical = col_colors.get(c, set())
            if len(colors | vertical) > 1 and vertical:
                out[r][c] = 0
            elif colors:
                out[r][c] = next(iter(colors))
    for c, colors in col_colors.items():
        for r in range(h):
            horizontal = row_colors.get(r, set())
            if len(colors | horizontal) > 1 and horizontal:
                out[r][c] = 0
            elif colors:
                out[r][c] = next(iter(colors))
    return out
